metadata.er-schema:
{
  "title": "looply · 库存系统 实体关系图",
  "version": "v3.0 · 2026-05-12",
  "tables": [
    {
      "name": "inventory_item",
      "comment": "库存主体",
      "columns": [
        {
          "name": "inventory_item_id",
          "comment": "库存主体ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "product_id",
          "comment": "实物商品ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "quantity",
          "comment": "库存数量",
          "constraint": ""
        },
        {
          "name": "inventory_status",
          "comment": "库存状态",
          "constraint": ""
        },
        {
          "name": "location_type",
          "comment": "位置类型",
          "constraint": ""
        },
        {
          "name": "warehouse_id",
          "comment": "所在仓库",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "transit_type",
          "comment": "在途类型",
          "constraint": ""
        },
        {
          "name": "transit_ref_no",
          "comment": "在途关联单号",
          "constraint": ""
        },
        {
          "name": "cost_price",
          "comment": "单位成本",
          "constraint": ""
        },
        {
          "name": "currency",
          "comment": "成本币种",
          "constraint": ""
        },
        {
          "name": "entered_at",
          "comment": "入库时间",
          "constraint": ""
        },
        {
          "name": "last_moved_at",
          "comment": "最近移动时间",
          "constraint": ""
        }
      ],
      "note": "库存管理最小单元，混合模式下二手商品 quantity=1，标品 quantity≥1；直接关联商品系统的 product"
    },
    {
      "name": "inventory_ledger",
      "comment": "库存流水",
      "columns": [
        {
          "name": "ledger_id",
          "comment": "流水ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "inventory_item_id",
          "comment": "库存主体ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "event_type",
          "comment": "事件类型",
          "constraint": ""
        },
        {
          "name": "quantity_change",
          "comment": "数量变化",
          "constraint": ""
        },
        {
          "name": "from_status",
          "comment": "变动前状态",
          "constraint": ""
        },
        {
          "name": "to_status",
          "comment": "变动后状态",
          "constraint": ""
        },
        {
          "name": "from_location",
          "comment": "变动前位置",
          "constraint": ""
        },
        {
          "name": "to_location",
          "comment": "变动后位置",
          "constraint": ""
        },
        {
          "name": "ref_type",
          "comment": "关联单据类型",
          "constraint": ""
        },
        {
          "name": "ref_no",
          "comment": "关联单据号",
          "constraint": ""
        },
        {
          "name": "operator_id",
          "comment": "操作人ID",
          "constraint": ""
        },
        {
          "name": "operator_type",
          "comment": "操作人类型",
          "constraint": ""
        },
        {
          "name": "occurred_at",
          "comment": "发生时间",
          "constraint": ""
        },
        {
          "name": "remark",
          "comment": "备注",
          "constraint": ""
        }
      ],
      "note": "每次库存变动记录一条流水，支持追溯和对账"
    },
    {
      "name": "channel_inventory_allocation",
      "comment": "渠道库存分配",
      "columns": [
        {
          "name": "allocation_id",
          "comment": "分配ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "inventory_item_id",
          "comment": "库存主体ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "channel_id",
          "comment": "渠道ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "listing_id",
          "comment": "渠道商品ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "allocated_quantity",
          "comment": "分配数量",
          "constraint": ""
        },
        {
          "name": "available_quantity",
          "comment": "可售数量",
          "constraint": ""
        },
        {
          "name": "reserved_quantity",
          "comment": "预占数量",
          "constraint": ""
        },
        {
          "name": "locked_quantity",
          "comment": "锁定数量",
          "constraint": ""
        },
        {
          "name": "allocation_status",
          "comment": "分配状态",
          "constraint": ""
        },
        {
          "name": "reserved_order_no",
          "comment": "预占订单号",
          "constraint": ""
        },
        {
          "name": "reserved_at",
          "comment": "预占时间",
          "constraint": ""
        },
        {
          "name": "reserve_expire_at",
          "comment": "预占过期时间",
          "constraint": ""
        },
        {
          "name": "locked_at",
          "comment": "锁定时间",
          "constraint": ""
        },
        {
          "name": "locked_reason",
          "comment": "锁定原因",
          "constraint": ""
        },
        {
          "name": "activity_id",
          "comment": "活动ID",
          "constraint": "FOREIGN KEY"
        }
      ],
      "note": "记录库存主体在各渠道的分配，支持多渠道售卖和预占/锁定"
    }
  ],
  "relations": [
    {
      "from": "inventory_item",
      "to": "inventory_ledger",
      "type": "1:N",
      "label": "产生流水",
      "color": "#E8833A",
      "penwidth": 1.4
    },
    {
      "from": "inventory_item",
      "to": "channel_inventory_allocation",
      "type": "1:N",
      "label": "分配到渠道",
      "color": "#8E24AA",
      "penwidth": 1.4
    },
    {
      "from": "inventory_item",
      "to": "warehouse",
      "type": "N:1",
      "label": "所在仓库（仓储模块）",
      "style": "dashed",
      "color": "#43A047"
    },
    {
      "from": "inventory_item",
      "to": "product",
      "type": "N:1",
      "label": "关联实物商品",
      "style": "dashed",
      "color": "#999999"
    },
    {
      "from": "channel_inventory_allocation",
      "to": "channel",
      "type": "N:1",
      "label": "所属渠道",
      "style": "dashed",
      "color": "#999999"
    },
    {
      "from": "channel_inventory_allocation",
      "to": "listing",
      "type": "N:1",
      "label": "关联渠道商品",
      "style": "dashed",
      "color": "#999999"
    }
  ],
  "design_rules": {
    "库存单元": "inventory_item 是库存管理最小单元，混合模式下二手商品 quantity=1，标品 quantity≥1；直接关联商品系统的 product",
    "三层架构": "仓储模块负责仓库和物理操作，库存模块负责中央库存、渠道分配和流水台账",
    "流水台账": "每次库存变动记录一条 inventory_ledger 流水，quantity_change 记录数量变化（二手商品 ±1，标品 ±N）",
    "多渠道售卖": "同一库存主体可分配到多渠道；二手商品下单时排他预占，标品按数量分配",
    "渠道数量拆分": "allocated_quantity = available_quantity + reserved_quantity + locked_quantity",
    "预占超时释放": "reserve_expire_at + 定时任务扫描，超时未支付自动释放预占数量",
    "状态分离": "inventory_status（物理流转）与商品系统的 item_status（业务生命周期）分离管理，事件驱动同步",
    "分仓管理": "库存模块只引用 warehouse_id；warehouse 归仓储模块管理",
    "外部引用": "product/channel/listing/warehouse 为外部实体，虚线表示跨模块引用"
  }
}
